using System;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
public class CPHInline {
 const string StateKey="portable.redeems.state",MapKey="managedRedeemRewardsJson",BacklogKey="managedRedeemDockBacklogJson",Version="1.0.0";
 string Arg(string key){try{return args.ContainsKey(key)&&args[key]!=null?args[key].ToString().Trim():"";}catch{return "";}}
 protected virtual long Now(){return DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();}
 string Read(string key){try{return CPH.GetGlobalVar<string>(key,true)??"";}catch{return "";}}
 JObject Object(string value){try{return JObject.Parse(value??"");}catch{return new JObject();}}
 JArray Array(string value){try{return JArray.Parse(value??"");}catch{return new JArray();}}
 JObject Envelope(){return Object(Read(StateKey));}
 JObject Load(){JObject payload=Envelope()["payload"] as JObject;if(payload==null)payload=new JObject();if(!(payload["pending"] is JArray))payload["pending"]=new JArray();if(!(payload["history"] is JArray))payload["history"]=new JArray();payload["version"]=1;payload["moduleVersion"]=Version;return payload;}
 long Revision(){return (long?)Envelope()["revision"]??0;}
 void Save(JObject payload){payload["version"]=1;payload["moduleVersion"]=Version;payload["serverTimeMs"]=Now();JArray history=(JArray)payload["history"];while(history.Count>50)history.RemoveAt(history.Count-1);JObject envelope=new JObject{{"schemaVersion",1},{"feature","redeems"},{"type","state"},{"revision",Revision()+1},{"payload",payload}};string json=envelope.ToString(Formatting.None);CPH.SetGlobalVar(StateKey,json,true);try{CPH.WebsocketBroadcastJson(json);}catch{}}
 string Category(string value){return String.Equals(value,"writing",StringComparison.OrdinalIgnoreCase)?"writing":"live";}
 bool AddItem(JObject payload,JObject item){string id=(string)item["redemptionId"]??"";if(String.IsNullOrWhiteSpace(id))return false;foreach(JObject value in (JArray)payload["pending"])if((string)value["redemptionId"]==id)return false;foreach(JObject value in (JArray)payload["history"])if((string)value["redemptionId"]==id)return false;item["category"]=Category((string)item["category"]);if(item["receivedAtMs"]==null)item["receivedAtMs"]=Now();item["status"]="pending";item["requestedAction"]="";item["lastError"]="";((JArray)payload["pending"]).Add(item);return true;}
 JObject Item(){string input=Arg("rawInput");if(String.IsNullOrWhiteSpace(input))input=Arg("userInput");return new JObject{{"rewardId",Arg("rewardId")},{"redemptionId",Arg("redemptionId")},{"rewardTitle",Arg("rewardTitle")},{"category",Category(Arg("category"))},{"userLogin",Arg("userName")},{"userName",Arg("user")},{"userInput",input},{"redeemedAt",Arg("redeemedAt")}};}
 int Migrate(JObject payload){JArray backlog=Array(Read(BacklogKey));int added=0;foreach(JObject item in backlog)if(AddItem(payload,(JObject)item.DeepClone()))added++;if(backlog.Count>0){Save(payload);CPH.SetGlobalVar(BacklogKey,"[]",true);}return added;}
 bool Initialize(){JObject payload=Load();JArray backlog=Array(Read(BacklogKey));if(backlog.Count>0)Migrate(payload);else Save(payload);return true;}
 bool Add(){JObject payload=Load();if(AddItem(payload,Item()))Save(payload);return true;}
 bool MigrateOnly(){JObject payload=Load();int count=Migrate(payload);if(count>0)CPH.LogInfo("[Redeems] Migrated "+count+" legacy backlog item(s).");return true;}
 string Language(JObject config){string value=((string)config["language"]??"").Trim().ToLowerInvariant();if(value=="german"||value=="french"||value=="dutch")return value;string title=((string)config["title"]??"").ToLowerInvariant();return title.Contains("german")?"german":title.Contains("french")?"french":title.Contains("dutch")?"dutch":"";}
 bool Route(){string reward=Arg("rewardId"),redemption=Arg("redemptionId");CPH.SetArgument("redeemRouteKind","ignore");if(String.IsNullOrWhiteSpace(reward)||String.IsNullOrWhiteSpace(redemption))return true;JObject config=null;foreach(JObject item in Array(Read(MapKey)))if((string)item["id"]==reward){config=item;break;}if(config==null)return true;string kind=((string)config["kind"]??"checklist").ToLowerInvariant();if(kind=="language"){string language=Language(config);if(String.IsNullOrWhiteSpace(language)){CPH.LogError("[Redeems] Managed language reward has no supported language.");return true;}CPH.SetArgument("language",language);CPH.SetArgument("durationSeconds",(int?)config["durationSeconds"]??300);CPH.SetArgument("redeemRouteKind","language");return true;}CPH.SetArgument("rewardTitle",(string)config["title"]??Arg("rewardTitle"));CPH.SetArgument("category",Category((string)config["category"]));CPH.SetArgument("redeemRouteKind","checklist");return true;}
 bool Resolve(){JObject payload=Load();JArray pending=(JArray)payload["pending"];string id=Arg("redemptionId"),resolution=Arg("resolution").ToLowerInvariant()=="refund"?"refund":"complete";JObject item=null;int index=-1;for(int i=0;i<pending.Count;i++){JObject value=pending[i] as JObject;if((string)value?["redemptionId"]==id){item=value;index=i;break;}}if(item==null)throw new Exception("Pending redemption not found.");bool ok=false;string error="";try{ok=resolution=="refund"?CPH.TwitchRedemptionCancel((string)item["rewardId"],id):CPH.TwitchRedemptionFulfill((string)item["rewardId"],id);if(!ok)error="Twitch rejected the redemption update.";}catch(Exception ex){error=ex.Message;}if(!ok){item["status"]="error";item["requestedAction"]=resolution;item["lastError"]=error;Save(payload);CPH.SetArgument("redeemResolveSuccess",false);CPH.SetArgument("redeemResolveError",error);return true;}pending.RemoveAt(index);item["status"]=resolution=="refund"?"refunded":"completed";item["requestedAction"]=resolution;item["resolvedAtMs"]=Now();item["lastError"]="";((JArray)payload["history"]).Insert(0,item);Save(payload);CPH.SetArgument("redeemResolveSuccess",true);CPH.SetArgument("redeemResolveError","");return true;}
 bool Health(){JObject payload=Load();CPH.LogInfo("[Redeems] Health OK: "+((JArray)payload["pending"]).Count+" pending, "+((JArray)payload["history"]).Count+" history item(s), module "+Version+".");return true;}
 public bool Execute(){string mode=Arg("redeemMode").ToLowerInvariant();try{if(mode=="initialize")return Initialize();if(mode=="health")return Health();if(mode=="add")return Add();if(mode=="route")return Route();if(mode=="migrate")return MigrateOnly();if(mode=="resolve")return Resolve();throw new Exception("Unknown redeem mode.");}catch(Exception error){CPH.LogError("[Redeems] "+error.Message);CPH.SetArgument("redeemResolveSuccess",false);CPH.SetArgument("redeemResolveError",error.Message);return true;}}
}
